export type TypeMarketing =
  | "hypermotion"
  | "2d_motion"
  | "saas_motion"
  | "mixed_media"
  | "product_shots"
  | "product_shots_people";

export type MarketingPreset = {
  id: string;
  nom: string;
  type: TypeMarketing;
  preview: string;
  previewType: "image" | "video";
  poster: string;
};

// Categories du filtre Marketing Studio, dans l'ordre d'affichage.
